import{printedArtwork}from'../../modeling/artwork.js';import{spec}from'./dimensions.js';const sources={front:new URL('./source-vector-front.png',import.meta.url).href,back:new URL('./source-vector-back.png',import.meta.url).href};export function addStickers(host){const result=[];for(const face of['front','back']){const v=spec.labels[face],position=[...v.position];if(face==='front')position[2]+=.05;result.push(...printedArtwork(host,{target:host.ssrAssembly.labels[face],url:sources[face],size:v.size,position,face,depth:.1,name:'SSR exact U122 '+face+' body-label raster',artworkKind:face==='front'?'source-vector-raster-and-reference-redraw':'source-vector-raster'})??[]);}return result;}
